import { api,setCsrf,setOfflineScope,syncQueue,ApiError } from './api.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const TUTORIAL_VERSION=1;const state={me:null,page:'today',filter:'pending',scanMode:null,scanFile:null,scanOcrFile:null,scanQuality:null,scanDetectedBarcode:null,scanProductLookup:null,scanPreviewUrl:null,scanBusy:false,scanSession:null,scanSessionItems:[],scanSessionBusy:false,allMenu:false,supplierTab:'needs',supplierProducts:[],suppliers:[],supplierOrders:[],invoiceImport:null,team:[],temperatureAlertTimer:null,tutorialOpen:false};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?new Date(d).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'}):'—';
const days=d=>Math.max(0,Math.ceil((new Date(d)-Date.now())/86400000));
const iconBase='/assets/hygiesafe-icons/';const iconMap={home:'home.png',profile:'profile.png',team:'team.png',scanner:'scanner.png',temperature:'temperature.png',controls:'controls.png',schedule:'schedule.png',inventory:'inventory.png',orders:'orders.png',archive:'archive.png'};
const hsIcon=(name,cls='hs-inline-icon')=>`<img class="${cls}" src="${iconBase}${iconMap[name]||iconMap.controls}" alt="">`;
function toast(message,bad=false){let el=document.createElement('div');el.className='offline';el.style.background=bad?'#8c2d2d':'#184f34';el.textContent=message;document.body.append(el);setTimeout(()=>el.remove(),2600)}
function modal(title,html,{locked=false}={}){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden');$('#modalClose').classList.toggle('hidden',locked);$('#modalClose').onclick=()=>{if(!locked)closeModal()}}
function closeModal(){$('#modal').classList.add('hidden');$('#modalBody').innerHTML=''}
function formDataObj(form){return Object.fromEntries(new FormData(form).entries())}
function isOwner(){return state.me?.user.role==='owner'}function isManager(){return ['owner','manager'].includes(state.me?.user.role)}
function roleLabel(role=state.me?.user.role){return role==='owner'?'Gérant':role==='manager'?'Responsable':'Employé'}
function roleUi(){
  $$('.owner,.owner-only').forEach(x=>x.classList.toggle('hidden',!isOwner()));$$('.owner-hidden').forEach(x=>x.classList.toggle('hidden',isOwner()));$$('.manager').forEach(x=>x.classList.toggle('hidden',!isManager()));$$('.manager-only').forEach(x=>x.classList.toggle('hidden',!isManager()));
  document.body.dataset.role=state.me?.user.role||'employee';if($('#roleBadge'))$('#roleBadge').textContent=roleLabel();
  if($('#startDayBtn'))$('#startDayBtn').textContent=isOwner()?'Voir les priorités':state.me?.user.role==='manager'?'Superviser les contrôles':'Voir mes tâches';
}
function go(page){state.page=page;$$('.page').forEach(p=>p.classList.toggle('on',p.id===`page-${page}`));$$('[data-page]').forEach(b=>b.classList.toggle('on',b.dataset.page===page));window.scrollTo(0,0);loadPage(page).catch(handleError)}
function handleError(e){if(e instanceof ApiError&&e.status===401)return location.href='/login.html';if(e instanceof ApiError&&e.code==='email_verification_required')return location.href='/verify-email.html';if(e instanceof ApiError&&e.status===402){go('subscription');toast(e.message,true);return}console.error(e);toast(e.message||'Une erreur est survenue.',true)}
async function init(){
  try{state.me=await api('/api/auth/me');setCsrf(state.me.csrf);setOfflineScope(state.me.user?.id,state.me.organization?.id)}catch{return location.href='/login.html'}
  if(!state.me.user.emailVerified)return location.href='/verify-email.html';
  $('#orgName').textContent=state.me.organization.name;$('#avatar').textContent=state.me.user.name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();roleUi();bindUi();await syncQueue();
  await refreshTemperatureAlert();state.temperatureAlertTimer=setInterval(()=>refreshTemperatureAlert().catch(()=>{}),60000);
  if(isOwner()&&!state.me.organization.onboarding_completed){await onboarding();return}
  const start=location.hash.replace('#','');go(['billing','billing-success'].includes(start)?'subscription':'today');
  setTimeout(()=>maybeShowRoleTutorial().catch(()=>{}),450);
}
function bindUi(){
  $$('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#profileBtn').onclick=()=>go('profile');$('#helpBtn').onclick=()=>go('help');$('#logoutBtn').onclick=logout;$('#toggleAll').onclick=()=>{state.allMenu=!state.allMenu;$('#sidebar').classList.toggle('all',state.allMenu);$('#toggleAll').textContent=state.allMenu?'− Réduire':'＋ Plus de fonctions'};$('#menuToggle').onclick=()=>{state.allMenu=!state.allMenu;$('#menuCards').classList.toggle('all',state.allMenu);$('#menuToggle').textContent=state.allMenu?'Réduire':'Plus de fonctions'};
  $$('[data-new]').forEach(b=>b.onclick=()=>openRecordForm(b.dataset.new));$$('[data-action="new-temperature"]').forEach(b=>b.onclick=()=>openTemperatureForm());$$('[data-action="new-traceability"]').forEach(b=>b.onclick=()=>openRecordForm('traceability'));
  $$('.scan-card').forEach(b=>b.onclick=()=>startScan(b.dataset.scan));$('#scanFile').onchange=scanFileSelected;$('#startSeriesScan').onclick=()=>startScanSession('series');$('#startReceptionScan').onclick=()=>startScanSession('reception');$('#productCatalogBtn').onclick=openRecognizedProducts;$('#inviteBtn').onclick=openInvite;$('#clockBtn').onclick=clockToggle;$('#startDayBtn').onclick=()=>go('controls');
  $$('.filters button').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;$$('.filters button').forEach(x=>x.classList.toggle('on',x===b));loadControls()});
  window.addEventListener('offline',()=>$('#offlineBanner').classList.remove('hidden'));window.addEventListener('online',()=>$('#offlineBanner').classList.add('hidden'));if(!navigator.onLine)$('#offlineBanner').classList.remove('hidden');
}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}location.href='/login.html'}
async function loadPage(page){const map={today:loadToday,controls:loadControls,traceability:loadTraceability,reception:()=>loadRecordList('reception'),inventory:loadInventory,suppliers:loadSuppliers,nonconformity:()=>loadRecordList('nonconformity'),equipment:()=>loadRecordList('equipment'),tasks:()=>loadRecordList('task'),team:loadTeam,timeclock:()=>loadRecordList('timeclock'),documents:()=>loadRecordList('document'),oils:()=>loadRecordList('oil'),pests:()=>loadRecordList('pest'),allergens:()=>loadRecordList('allergen'),history:loadHistory,audit:loadAudit,subscription:loadBilling,profile:loadProfile,establishment:loadEstablishment,reports:async()=>{},scanner:loadScannerWorkspace,menu:loadMenu,help:loadHelp};return (map[page]||(()=>{}))()}
async function loadToday(){
  const [d,b]=await Promise.all([api('/api/records/dashboard'),api('/api/billing/status')]);
  const role=state.me.user.role,name=esc(state.me.user.name.split(/\s+/)[0]||state.me.user.name);
  const roleCopy=role==='owner'
    ?{title:`Bonjour ${name}, voici votre établissement aujourd’hui.`,text:'Supervisez les urgences, l’équipe et les contrôles sans parcourir tous les menus.',icon:'home'}
    :role==='manager'
      ?{title:`Bonjour ${name}, voici les priorités de l’équipe.`,text:'Traitez les contrôles et anomalies, puis vérifiez que les relevés prévus sont bien réalisés.',icon:'team'}
      :{title:`Bonjour ${name}, voici ce que vous avez à faire.`,text:'Les actions importantes apparaissent ici. Les températures s’affichent seulement à vos heures prévues.',icon:'controls'};
  $('#roleWelcome').innerHTML=`<div class="role-welcome-main">${hsIcon(roleCopy.icon,'role-welcome-icon')}<div><span class="role-kicker">${roleLabel(role)}</span><b>${roleCopy.title}</b><small>${roleCopy.text}</small></div></div><button class="small-btn" id="todayTutorialBtn">Voir mon tutoriel</button>`;
  $('#todayTutorialBtn').onclick=()=>openRoleTutorial(role,{markComplete:true});
  $('#todayKpis').innerHTML=[['À faire',d.pending],['Anomalies',d.nonconformities],['DLC proches',d.expiring],['Relevés',d.temperaturesToday]].map(([l,v])=>`<div class="kpi"><b>${v}</b><small>${l}</small></div>`).join('');
  let title='Tout est à jour',text=role==='employee'?'Vous n’avez aucune action urgente pour le moment.':'Aucune action urgente détectée.';
  if(d.pending){title=`${d.pending} action${d.pending>1?'s':''} à terminer`;text=role==='employee'?'Ouvrez vos contrôles et faites seulement les actions affichées.':'Commencez par les contrôles en attente.'}
  else if(d.nonconformities){title='Une anomalie demande votre attention';text='Ouvrez les non-conformités.'}
  $('#nextAction').innerHTML=`<span class="next-kicker">Prochaine action</span><h2>${title}</h2><p>${text}</p><button class="btn" style="background:white;color:#075f38" data-go-controls>${d.pending?'Commencer':'Voir les contrôles'}</button>`;
  $('#nextAction [data-go-controls]').onclick=()=>go(d.nonconformities&&!d.pending?'nonconformity':'controls');
  const priorities=[];if(d.nonconformities)priorities.push(['controls',`${d.nonconformities} non-conformité(s)`,'À traiter']);if(d.expiring)priorities.push(['schedule',`${d.expiring} DLC/DDM proche(s)`,'Vérifier']);if(d.pending)priorities.push(['controls',`${d.pending} action(s) restante(s)`,'Faire']);
  $('#priorityList').innerHTML=priorities.length?priorities.map(([i,txt,a])=>`<div class="item"><div class="item-main"><b class="control-kind">${hsIcon(i,'hs-nav-icon')} ${txt}</b></div><span class="badge amber">${a}</span></div>`).join(''):'<div class="empty"><b>Rien d’urgent.</b><small>Vous pouvez continuer votre journée normalement.</small></div>';
  const quickByRole={
    owner:[['controls','controls','Contrôles','Voir les relevés et validations'],['team','team','Équipe','Membres et horaires'],['suppliers','orders','Commandes','Besoins et fournisseurs'],['reports','archive','Rapports','PDF HACCP et sauvegardes']],
    manager:[['controls','controls','Contrôles','Suivre les actions du jour'],['team','team','Équipe','Horaires des employés'],['scanner','scanner','Scanner','DLC, étiquettes et codes'],['suppliers','orders','Commandes','Préparer les besoins']],
    employee:[['controls','controls','Mes contrôles','Uniquement ce qui est à faire'],['scanner','scanner','Scanner','DLC, facture ou code-barres'],['traceability','controls','Traçabilité','Lots et produits ouverts'],['suppliers','orders','Commandes','Indiquer les quantités à prévoir']]
  };
  const quick=$('#page-today .quick');if(quick)quick.innerHTML=quickByRole[role].map(([page,icon,label,desc])=>`<button data-quick-page="${page}"><b>${hsIcon(icon,'hs-nav-icon')}${label}</b><small>${desc}</small></button>`).join('');$$('[data-quick-page]').forEach(x=>x.onclick=()=>go(x.dataset.quickPage));
  if(isOwner()){$('#trialCard').innerHTML=`<h3>${b.subscription_status==='active'?'Abonnement actif':`Essai : ${b.trialDaysLeft} jour(s) restant(s)`}</h3><p class="muted">${b.subscription_status==='active'?`${(b.monthly_amount_cents/100).toFixed(2).replace('.',',')} €/mois`:'Aucune carte bancaire demandée pendant l’essai.'}</p><button class="btn" id="todayBilling">Gérer</button>`;$('#todayBilling').onclick=()=>go('subscription')}
  await refreshTemperatureAlert();
}
async function loadControls(){if(state.filter==='pending'){const actions=await api('/api/records/today-actions');$('#controlsList').innerHTML=actions.length?actions.map(a=>`<div class="item"><div class="item-main"><b class="control-kind">${hsIcon(a.kind==='temperature'?'temperature':'controls','hs-nav-icon')} ${esc(a.title)}</b><small>${esc(a.detail||'')}${a.kind==='temperature'&&a.scheduledAt?` · <span class="temperature-slot-badge ${a.overdue?'overdue':''}">${esc(a.slotLabel)} ${esc(a.scheduledAt)}</span>`:''}</small></div><button class="btn primary" data-action-kind="${a.kind}" data-action-id="${a.id}" data-action-slot="${a.slot||''}" data-action-date="${a.scheduleDate||''}">${a.kind==='temperature'?'Relever':'Valider'}</button></div>`).join(''):'<div class="empty">Tout est fait pour le moment. Les relevés employés apparaissent uniquement à l’heure prévue.</div>';$$('[data-action-kind]').forEach(b=>b.onclick=async()=>{if(b.dataset.actionKind==='temperature')return openTemperatureForm(b.dataset.actionId,{slot:b.dataset.actionSlot||null,scheduleDate:b.dataset.actionDate||null});await api(`/api/records/today-actions/task/${b.dataset.actionId}/complete`,{method:'POST',body:{}});toast('Contrôle validé');loadControls()});return;}const rows=await api('/api/records?limit=300');const controls=rows.filter(r=>['temperature','cleaning'].includes(r.type));const filtered=state.filter==='done'?controls.filter(r=>['done','closed','completed'].includes(r.status)):controls;$('#controlsList').innerHTML=filtered.length?filtered.map(recordItem).join(''):'<div class="empty">Aucun contrôle dans cette vue.</div>';bindRecordActions('#controlsList')}
async function loadTraceability(){const rows=await api('/api/records?limit=300');const list=rows.filter(r=>['traceability','opened_product','supplier_lot'].includes(r.type));$('#traceabilityList').innerHTML=list.length?list.map(recordItem).join(''):'<div class="empty">Aucun produit enregistré. Utilisez Scanner pour gagner du temps.</div>';bindRecordActions('#traceabilityList')}
async function loadRecordList(type){const box=$(`.record-list[data-type="${type}"]`);if(!box)return;const rows=await api(`/api/records?type=${encodeURIComponent(type)}&limit=300`);box.innerHTML=rows.length?rows.map(recordItem).join(''):`<div class="empty">Aucun élément pour le moment.</div>`;bindRecordActions(`.record-list[data-type="${type}"]`)}
function recordItem(r){const p=r.payload||{};const details=[p.product,p.supplier,p.lot,p.expiry||p.dlc,p.value!=null?`${p.value}${p.unit||''}`:null,p.detail,p.frequency].filter(Boolean).slice(0,3).join(' · ');return `<div class="item" data-id="${r.id}" data-type="${r.type}"><div class="item-main"><b>${esc(r.title||labelType(r.type))}</b><small>${esc(details||fmt(r.occurred_at))}</small></div><div style="display:flex;gap:6px;align-items:center"><span class="badge ${['closed','done','completed'].includes(r.status)?'green':r.status==='late'?'red':''}">${esc(r.status)}</span>${!['timeclock'].includes(r.type)?`<button class="small-btn" data-record-menu="${r.id}">⋯</button>`:''}</div></div>`}
function labelType(t){return ({temperature:'Température',reception:'Réception',nonconformity:'Non-conformité',equipment:'Équipement',task:'Tâche',document:'Document',oil:'Huile',pest:'Nuisible',allergen:'Allergène',traceability:'Traçabilité',stock_article:'Article',timeclock:'Pointage'})[t]||t}
function bindRecordActions(sel){$$(sel+' [data-record-menu]').forEach(b=>b.onclick=async()=>{const item=b.closest('.item');modal('Action',`<p><b>${esc(item.querySelector('b').textContent)}</b></p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="markDone">Marquer terminé</button>${isManager()?'<button class="btn danger" id="deleteRecord">Supprimer</button>':''}</div>`);$('#markDone').onclick=async()=>{await api(`/api/records/${item.dataset.id}`,{method:'PATCH',body:{status:'done'}});closeModal();loadPage(state.page)};if($('#deleteRecord'))$('#deleteRecord').onclick=async()=>{if(!confirm('Supprimer cet élément ?'))return;await api(`/api/records/${item.dataset.id}`,{method:'DELETE'});closeModal();loadPage(state.page)}})}
async function loadInventory(){const rows=await api('/api/records?type=stock_article&limit=500');const low=rows.filter(r=>Number(r.payload?.quantity||0)<=Number(r.payload?.minStock||0)&&Number(r.payload?.minStock||0)>0).length;$('#inventoryKpis').innerHTML=`<div class="kpi"><b>${rows.length}</b><small>Références</small></div><div class="kpi"><b>${low}</b><small>Stocks faibles</small></div>`;const box=$('.record-list[data-type="stock_article"]');box.innerHTML=rows.length?rows.map(recordItem).join(''):'<div class="empty">Aucun article. Scannez une facture ou ajoutez un produit.</div>';bindRecordActions('.record-list[data-type="stock_article"]')}
async function loadTeam(){const rows=await api('/api/auth/team');state.team=rows;$('#teamList').innerHTML=rows.map(u=>{const canSchedule=u.role==='employee'&&isManager();return `<div class="item"><div class="item-main"><b>${esc(u.name)}</b><small>${esc(u.email)} · ${u.role==='owner'?'Gérant principal':u.role==='manager'?'Responsable':'Employé'}${u.last_login_at?` · dernière connexion ${fmt(u.last_login_at)}`:''}</small>${u.role==='employee'?`<div class="schedule-summary">${hsIcon('schedule','')}<span>${scheduleSummary(u.schedule)}</span></div>`:''}</div><div class="team-actions"><span class="badge ${u.active?'green':'red'}">${u.active?'Actif':'Désactivé'}</span>${canSchedule?`<button class="small-btn" data-schedule-user="${u.id}">${hsIcon('schedule')}Horaires</button>`:''}</div></div>`}).join('');$$('[data-schedule-user]').forEach(b=>b.onclick=()=>openScheduleEditor(b.dataset.scheduleUser))}
