function openRecordForm(type,prefill={}){const fs=fields[type]||[['detail','Détail']];modal(`Ajouter · ${labelType(type)}`,`<form id="recordForm"><div class="field"><label>Nom / titre</label><input name="title" value="${esc(prefill.product||prefill.title||'')}"></div><div class="form-grid">${fs.map(([n,l,t='text'])=>`<div class="field"><label>${l}</label><input name="${n}" type="${t}" value="${esc(prefill[n]||'')}"></div>`).join('')}</div>${type==='document'?'<div class="field"><label>Fichier (facultatif)</label><input name="file" type="file" accept="image/*,application/pdf"></div>':''}<button class="btn primary">Enregistrer</button></form>`);$('#recordForm').onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const title=fd.get('title')||labelType(type);const payload={...(prefill.__extra||{})};for(const [n] of fs)payload[n]=fd.get(n)||null;if(type==='document'&&fd.get('file')?.size){const up=new FormData();up.append('file',fd.get('file'));up.append('kind','document');const m=await api('/api/media/upload',{method:'POST',body:up});payload.mediaId=m.id}if(prefill.__scanFile?.size){const up=new FormData();up.append('file',prefill.__scanFile);up.append('kind',type==='reception'?'scan_reception':'scan_traceability');const m=await api('/api/media/upload',{method:'POST',body:up});payload.scanMediaId=m.id}const saved=await api('/api/records',{method:'POST',body:{type,title,status:type==='nonconformity'?'open':'active',payload},queueOffline:true});if(prefill.__rememberProduct?.code){api(`/api/scanner/products/${encodeURIComponent(prefill.__rememberProduct.code)}/remember`,{method:'POST',body:{name:payload.product||title}}).catch(()=>{})}closeModal();toast('Enregistré');loadPage(state.page)}}
async function openTemperatureForm(preselectedId=null,scheduleAction=null){if(state.me?.user.role==='employee'&&!scheduleAction?.slot)return toast('Le relevé sera disponible automatiquement à l’heure prévue.',true);const eq=await api('/api/records?type=equipment&limit=100');const slotText=scheduleAction?.slot?`<div class="schedule-help">${hsIcon('temperature','')}<span><b>Relevé ${scheduleAction.slot==='start'?'d’arrivée':'de départ'}</b><br>Ce contrôle est lié à votre horaire de travail.</span></div>`:'';modal('Nouveau relevé',`${slotText}<form id="tempForm"><div class="field"><label>Équipement</label><select name="equipmentId">${eq.map(x=>`<option value="${x.id}" ${preselectedId===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="field"><label>Température °C</label><input name="value" type="number" step="0.1" required inputmode="decimal"></div><button class="btn primary">Valider le relevé</button></form>`);$('#tempForm').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),eqr=eq.find(x=>x.id===f.get('equipmentId')),value=Number(f.get('value')),min=Number(eqr?.payload?.min),max=Number(eqr?.payload?.max),conforme=(!Number.isFinite(min)||value>=min)&&(!Number.isFinite(max)||value<=max);const payload={equipmentId:f.get('equipmentId'),value,unit:' °C',min:eqr?.payload?.min,max:eqr?.payload?.max,conforme};if(scheduleAction?.slot){payload.scheduleSlot=scheduleAction.slot;payload.scheduleDate=scheduleAction.scheduleDate||null}await api('/api/records',{method:'POST',body:{type:'temperature',title:eqr?.title||'Température',status:conforme?'done':'late',payload},queueOffline:state.me?.user.role!=='employee'});if(!conforme)await api('/api/records',{method:'POST',body:{type:'nonconformity',title:`Température hors seuil — ${eqr?.title}`,status:'open',payload:{detail:`${value} °C hors seuil`,source:'temperature'}}});closeModal();toast(conforme?'Relevé conforme':'Hors seuil : anomalie créée',!conforme);await refreshTemperatureAlert();loadControls();if(state.page==='today')loadToday()}}

function scanModeInfo(mode=state.scanMode){return ({dlc:{title:'Scanner une DLC / DDM',hint:'Photographiez toute l’étiquette. La date et le numéro de lot doivent être lisibles.',loading:'Analyse de l’étiquette…',detail:'Recherche du produit, de la date, du lot et du code-barres.'},invoice:{title:'Scanner une facture',hint:'Posez la facture à plat et cadrez la page entière. Évitez les ombres sur les montants.',loading:'Analyse de la facture…',detail:'Recherche du fournisseur, des produits, quantités et montants.'},barcode:{title:'Scanner un code-barres',hint:'Cadrez le code-barres de près, bien à plat et avec suffisamment de lumière.',loading:'Lecture du code-barres…',detail:'Recherche du code EAN / GTIN.'}})[mode]||{title:'Scanner',hint:'Prenez une photo nette.',loading:'Analyse…',detail:'Lecture en cours.'}}
function clearScanPreview(){if(state.scanPreviewUrl){URL.revokeObjectURL(state.scanPreviewUrl);state.scanPreviewUrl=null}}
function startScan(mode){state.scanMode=mode;state.scanFile=null;state.scanOcrFile=null;state.scanQuality=null;state.scanDetectedBarcode=null;state.scanProductLookup=null;state.scanBusy=false;clearScanPreview();const info=scanModeInfo(mode),live=mode==='barcode'&&'BarcodeDetector'in window&&navigator.mediaDevices?.getUserMedia;modal(info.title,`<div class="scan-source-intro">${hsIcon(mode==='barcode'?'scanner':mode==='invoice'?'orders':'schedule','scan-source-icon')}<div><b>${esc(info.hint)}</b><small>Vous pourrez vérifier la photo avant de lancer l’analyse.</small></div></div><div class="scan-source-grid">${live?'<button class="scan-source-btn primary-source" id="scanLive"><b>Scanner en direct</b><small>Ouvre la caméra et détecte automatiquement le code</small></button>':''}<button class="scan-source-btn" id="scanCamera"><b>Prendre une photo</b><small>Utiliser l’appareil photo arrière</small></button><button class="scan-source-btn" id="scanGallery"><b>Choisir une image</b><small>Utiliser une photo déjà enregistrée</small></button>${mode==='barcode'?'<button class="scan-source-btn" id="scanManual"><b>Saisir le code</b><small>Si la caméra ne le détecte pas</small></button>':''}</div>`);if($('#scanLive'))$('#scanLive').onclick=()=>{closeModal();openCameraBarcode()};$('#scanCamera').onclick=()=>chooseScanFile(true);$('#scanGallery').onclick=()=>chooseScanFile(false);if($('#scanManual'))$('#scanManual').onclick=()=>{closeModal();openManualBarcode()}}
function chooseScanFile(camera=false){closeModal();const input=$('#scanFile');input.value='';if(camera)input.setAttribute('capture','environment');else input.removeAttribute('capture');input.click()}
async function scanBitmap(file){if('createImageBitmap'in window){try{return await createImageBitmap(file,{imageOrientation:'from-image'})}catch{return createImageBitmap(file)}}return new Promise((resolve,reject)=>{const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=e=>{URL.revokeObjectURL(url);reject(e)};img.src=url})}
async function assessScanPhoto(file){try{const img=await scanBitmap(file),iw=img.width,ih=img.height,max=420,ratio=Math.min(1,max/Math.max(iw,ih)),w=Math.max(1,Math.round(iw*ratio)),h=Math.max(1,Math.round(ih*ratio)),c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0,w,h);const d=x.getImageData(0,0,w,h).data;let sum=0,bright=0,dark=0,edges=0,count=0,prev=null;for(let i=0;i<d.length;i+=16){const y=.2126*d[i]+.7152*d[i+1]+.0722*d[i+2];sum+=y;bright+=y>248;dark+=y<22;if(prev!=null)edges+=Math.abs(y-prev);prev=y;count++}img.close?.();const mean=sum/Math.max(1,count),sharp=edges/Math.max(1,count-1),warnings=[];if(Math.max(iw,ih)<900)warnings.push('résolution un peu faible');if(mean<48)warnings.push('photo trop sombre');if(mean>232)warnings.push('photo trop claire');if(bright/Math.max(1,count)>.66)warnings.push('reflet important possible');if(dark/Math.max(1,count)>.62)warnings.push('grande zone sombre');if(sharp<8)warnings.push('photo possiblement floue');const score=Math.max(28,100-warnings.length*16-(sharp<5?10:0));return {warnings,score,width:iw,height:ih,mean:Math.round(mean),sharpness:Math.round(sharp)}}catch{return {warnings:['qualité impossible à mesurer'],score:60}}}
async function prepareScanForOcr(file){try{const img=await scanBitmap(file),limit=state.scanMode==='invoice'?2600:2200,scale=Math.min(1,limit/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0,w,h);const image=x.getImageData(0,0,w,h),d=image.data,contrast=1.12;for(let i=0;i<d.length;i+=4){const y=.2126*d[i]+.7152*d[i+1]+.0722*d[i+2],v=Math.max(0,Math.min(255,(y-128)*contrast+128));d[i]=d[i+1]=d[i+2]=v}x.putImageData(image,0,0);img.close?.();return await new Promise(resolve=>c.toBlob(blob=>resolve(blob||file),'image/jpeg',.92))}catch{return file}}
async function supportedBarcodeFormats(){const wanted=['data_matrix','qr_code','ean_13','ean_8','upc_a','upc_e','code_128','itf','gs1_databar'];if(!('BarcodeDetector'in window))return [];try{if(BarcodeDetector.getSupportedFormats){const supported=await BarcodeDetector.getSupportedFormats();const out=wanted.filter(x=>supported.includes(x));return out.length?out:['ean_13','ean_8','code_128']}return ['ean_13','ean_8','upc_a','upc_e','code_128','itf']}catch{return ['ean_13','ean_8','code_128']}}
async function detectBarcodeFromImage(file){if(!('BarcodeDetector'in window))return null;try{const bitmap=await scanBitmap(file),detector=new BarcodeDetector({formats:await supportedBarcodeFormats()}),codes=await detector.detect(bitmap);bitmap.close?.();return codes[0]?.rawValue||null}catch{return null}}
function scanQualityStatus(){const score=Number(state.scanQuality?.score||0);return score>=82?{label:'Photo nette',cls:'good'}:score>=60?{label:'Photo à vérifier',cls:'medium'}:{label:'Photo à reprendre',cls:'bad'}}
async function scanFileSelected(){const file=$('#scanFile').files[0];if(!file)return;state.scanFile=file;state.scanOcrFile=null;state.scanBusy=false;state.scanQuality=await assessScanPhoto(file);state.scanDetectedBarcode=await detectBarcodeFromImage(file);clearScanPreview();state.scanPreviewUrl=URL.createObjectURL(file);renderScanPreview()}
function renderScanPreview(){const q=scanQualityStatus(),w=state.scanQuality?.warnings||[],info=scanModeInfo();$('#scanResult').classList.remove('hidden');$('#scanResult').innerHTML=`<div class="scan-preview-layout"><div class="scan-preview-photo"><img src="${state.scanPreviewUrl}" alt="Photo à analyser"></div><div class="scan-preview-side"><div class="scan-result-head"><div><h3>Vérifiez la photo</h3><small>${esc(info.hint)}</small></div><span class="scan-quality-score ${q.cls}">${Math.round(state.scanQuality?.score||0)}/100</span></div><div class="scan-quality-line ${q.cls}"><b>${q.label}</b><span>${w.length?esc(w.join(' · ')):'Cadrage et luminosité corrects.'}</span></div>${state.scanDetectedBarcode?`<div class="scan-detected-hint">Code-barres déjà détecté : <b>${esc(state.scanDetectedBarcode)}</b></div>`:''}<div class="scan-preview-checks"><span>✓ Document lisible</span><span>✓ Date / lot dans l’image</span><span>✓ Pas de reflet sur le texte</span></div><div class="scan-actions"><button class="btn primary" id="analyzeScan">Analyser maintenant</button><button class="btn ghost" id="scanRetake">Reprendre la photo</button></div></div></div>`;$('#analyzeScan').onclick=analyzeSelectedScan;$('#scanRetake').onclick=()=>startScan(state.scanMode)}
async function analyzeSelectedScan(){if(!state.scanFile||state.scanBusy)return;state.scanBusy=true;const info=scanModeInfo();$('#scanResult').innerHTML=`<div class="scan-loading enhanced"><div class="scan-spinner"></div><b>${esc(info.loading)}</b><small>${esc(info.detail)}</small><div class="scan-loading-steps"><span class="on">Photo</span><span class="on">Lecture</span><span>Base produits</span><span>Vérification</span></div></div>`;try{state.scanOcrFile=await prepareScanForOcr(state.scanFile);const fd=new FormData();fd.append('file',state.scanOcrFile,'scan-hygiesafe.jpg');fd.append('mode',state.scanMode==='invoice'?'invoice':'dlc');const r=await api('/api/media/scan',{method:'POST',body:fd});if(state.scanDetectedBarcode){let parsed=null;try{parsed=await api('/api/scanner/parse-code',{method:'POST',body:{rawCode:state.scanDetectedBarcode}})}catch{}if(parsed?.isGs1){r.ocr.gs1=parsed;r.ocr.barcode=r.ocr.barcode||parsed.gtin||state.scanDetectedBarcode;r.ocr.lot=r.ocr.lot||parsed.lot;r.ocr.date=r.ocr.date||parsed.expiryDate;r.ocr.expiryDate=r.ocr.expiryDate||parsed.expiryDate;r.ocr.dateType=r.ocr.dateType==='unknown'?(parsed.dateType||'unknown'):r.ocr.dateType;r.ocr.productionDate=r.ocr.productionDate||parsed.productionDate;if(parsed.weightKg!=null&&!r.ocr.weight){r.ocr.weight=parsed.weightKg;r.ocr.weightUnit='kg'}}else if(!r.ocr.barcode)r.ocr.barcode=state.scanDetectedBarcode}if(state.scanMode==='barcode'){const code=state.scanDetectedBarcode||r.ocr.barcode;if(code)return showBarcode(code);return showBarcodePhotoResult(r.ocr)}const lookupCode=String(r.ocr.barcode||'').replace(/\D/g,'');if(lookupCode.length>=8&&lookupCode.length<=14){const lookup=await lookupScannedProduct(lookupCode);if(lookup?.found){const product=lookup.product||{};r.ocr.internetProduct=product;r.ocr.fieldConfidence=r.ocr.fieldConfidence||{};const productConfidence=Number(r.ocr.fieldConfidence.product||0);if(!String(r.ocr.product||'').trim()||productConfidence<68){r.ocr.product=product.name||r.ocr.product;r.ocr.fieldConfidence.product=Math.max(92,productConfidence);r.ocr.productLookupApplied=true}}}showScanResult(r.ocr)}catch(e){handleError(e);renderScanPreview()}finally{state.scanBusy=false}}
function scanTypeLabel(type){return ({dlc:'DLC · à consommer jusqu’au',ddm:'DDM · de préférence avant',expiry:'Date limite',unknown:'À confirmer'})[type]||'À confirmer'}
function scanTempLabel(t){if(t?.min==null&&t?.max==null)return '';if(t.min==null)return `≤ ${t.max} °C`;if(t.max==null)return `≥ ${t.min} °C`;return t.min===t.max?`${t.min} °C`:`${t.min} à ${t.max} °C`}
function scanQualityHtml(){const w=state.scanQuality?.warnings||[];return w.length?`<div class="scan-warning"><b>Qualité de la photo</b><small>${esc(w.join(' · '))}</small></div>`:''}
function confidenceTag(score,label=''){score=Number(score||0);if(!score)return '<span class="field-confidence unknown">à vérifier</span>';const cls=score>=85?'good':score>=68?'medium':'bad';return `<span class="field-confidence ${cls}" title="Fiabilité de la lecture automatique">${label?esc(label)+' · ':''}${Math.round(score)} %</span>`}
function scanField(label,id,value,confidence,{type='text',placeholder=''}={}){const low=Number(confidence||0)>0&&Number(confidence)<68;return `<div class="field scan-field ${low?'needs-check':''}"><label>${label} ${confidenceTag(confidence)}</label><input id="${id}" type="${type}" value="${esc(value??'')}" placeholder="${esc(placeholder)}"></div>`}
function scanDateSuggestions(o){const rows=(o.dateCandidates||[]).filter(x=>['dlc','ddm','expiry','unknown'].includes(x.type));const seen=new Set(),unique=rows.filter(x=>{const k=`${x.date}|${x.type}`;if(seen.has(k))return false;seen.add(k);return true}).slice(0,5);if(unique.length<2)return '';return `<div class="scan-date-suggestions"><b>Plusieurs dates trouvées</b><small>Appuyez sur la bonne date si la proposition principale n’est pas correcte.</small><div>${unique.map(x=>`<button type="button" data-scan-date="${esc(x.date)}" data-scan-date-type="${esc(x.type)}">${esc(x.date.split('-').reverse().join('/'))}<span>${esc(scanTypeLabel(x.type).split(' · ')[0])}</span></button>`).join('')}</div></div>`}
function scanExtraMeta(o){const rows=[];if(o.gs1?.isGs1)rows.push('<span>GS1 / DataMatrix</span>');if(o.weight!=null)rows.push(`<span>${esc(String(o.weight).replace('.',','))} ${esc(o.weightUnit||'')}</span>`);if(o.storageTemperature?.min!=null||o.storageTemperature?.max!=null)rows.push(`<span>${hsIcon('temperature')} ${esc(scanTempLabel(o.storageTemperature))}</span>`);if(o.productionDate)rows.push(`<span>${hsIcon('schedule')} Production ${esc(o.productionDate.split('-').reverse().join('/'))}</span>`);if(o.frozenDate)rows.push(`<span>${hsIcon('temperature')} Surgelé ${esc(o.frozenDate.split('-').reverse().join('/'))}</span>`);return rows.length?`<div class="scan-meta">${rows.join('')}</div>`:''}
async function lookupScannedProduct(code,{refresh=false}={}){const clean=String(code||'').replace(/\D/g,'');if(clean.length<8||clean.length>14)return null;try{const r=await api(`/api/scanner/products/${encodeURIComponent(clean)}${refresh?'?refresh=1':''}`);state.scanProductLookup=r;return r}catch(e){console.warn('product lookup',e);state.scanProductLookup=null;return null}}
function productLookupHtml(lookup=state.scanProductLookup,{compact=false}={}){if(!lookup)return '';if(!lookup.found){const unavailable=lookup.temporarilyUnavailable;return `<div class="product-lookup-card not-found"><div class="product-lookup-main">${hsIcon('scanner','product-lookup-icon')}<div><span>Base produits</span><b>${unavailable?'Recherche Internet momentanément indisponible':'Produit non trouvé automatiquement'}</b><small>${unavailable?'Le scan reste utilisable. Réessayez plus tard ou renseignez le produit manuellement.':'Vous pouvez renseigner le nom une seule fois : HygieSafe le mémorisera pour cet établissement.'}</small></div></div>${lookup.gs1VerificationUrl?`<a class="small-btn" target="_blank" rel="noopener noreferrer" href="${esc(lookup.gs1VerificationUrl)}">Vérifier le GTIN avec GS1</a>`:''}</div>`}const p=lookup.product||{},src=p.sourceLabel||'Base produits',known=['hygiesafe_memory','hygiesafe_catalog'].includes(lookup.source||p.source),cacheLabel=known?' · déjà connu':lookup.cached?' · cache':'';return `<div class="product-lookup-card ${compact?'compact':''}">${p.imageUrl?`<img class="product-lookup-image" src="${esc(p.imageUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:hsIcon('inventory','product-lookup-icon')}<div class="product-lookup-copy"><span>${esc(src)}${cacheLabel}</span><b>${esc(p.name||'Produit')}</b><small>${[p.brand,p.quantityLabel,p.category].filter(Boolean).map(esc).join(' · ')||'Informations produit trouvées automatiquement'}</small>${!compact&&p.allergens?`<em>Allergènes : ${esc(p.allergens)}</em>`:''}<div class="product-lookup-links">${p.sourceUrl?`<a target="_blank" rel="noopener noreferrer" href="${esc(p.sourceUrl)}">Voir la source</a>`:''}${lookup.gs1VerificationUrl?`<a target="_blank" rel="noopener noreferrer" href="${esc(lookup.gs1VerificationUrl)}">Vérifier sur GS1</a>`:''}</div>${p.sourceAttribution?`<small class="product-attribution">${esc(p.sourceAttribution)}</small>`:''}</div></div>`}
function lookupRememberMeta(lookup=state.scanProductLookup){const p=lookup?.found?lookup.product:null;if(!p?.code)return null;return {code:p.code,source:p.source||lookup.source||null}}
function scanEvidenceFile(){return state.scanFile?.size>9*1024*1024?(state.scanOcrFile||state.scanFile):state.scanFile}
function scanPrefill(o){const dateType=$('#scanDateType')?.value||o.dateType||'unknown',weight=$('#scanWeight')?.value||'',storage=$('#scanStorage')?.value||'',productionDate=$('#scanProduction')?.value||o.productionDate||'',frozenDate=$('#scanFrozen')?.value||o.frozenDate||'',lookup=state.scanProductLookup?.found?state.scanProductLookup.product:null,barcodeValue=$('#scanBarcode')?.value||'',barcodeDigits=String(barcodeValue).replace(/\D/g,''),remember=(barcodeDigits.length>=8&&barcodeDigits.length<=14)?{code:barcodeDigits,source:lookup?.source||null}:lookupRememberMeta();return {product:$('#scanProduct')?.value||'',lot:$('#scanLot')?.value||'',expiry:$('#scanDate')?.value||'',dlc:$('#scanDate')?.value||'',barcode:$('#scanBarcode')?.value||'',__scanFile:scanEvidenceFile(),__rememberProduct:remember,__extra:{source:'scanner',product:$('#scanProduct')?.value||null,lot:$('#scanLot')?.value||null,expiry:$('#scanDate')?.value||null,dlc:$('#scanDate')?.value||null,barcode:$('#scanBarcode')?.value||null,dateType,productionDate:productionDate||null,frozenDate:frozenDate||null,thawedDate:o.thawedDate||null,weight:weight||null,weightUnit:o.weightUnit||null,storageTemperature:storage||null,ocrConfidence:o.ocrConfidence||null,scanConfidence:o.confidence||null,photoQuality:state.scanQuality?.score||null,scanVerified:true,productLookup:lookup?{code:lookup.code,source:lookup.source||null,sourceUrl:lookup.sourceUrl||null,sourceLicense:lookup.sourceLicense||null,validatedByUser:true}:null}}}
function validateTraceScan(o){const product=$('#scanProduct')?.value.trim(),date=$('#scanDate')?.value,lot=$('#scanLot')?.value.trim();if(!product){$('#scanProduct')?.focus();return toast('Vérifiez ou renseignez le nom du produit.',true),false}if(!date){$('#scanDate')?.focus();return toast('Vérifiez ou renseignez la date limite.',true),false}if(!lot&&!confirm('Aucun numéro de lot n’est renseigné. Voulez-vous continuer quand même ?'))return false;return true}
async function confirmNoDuplicate(prefill={}){try{const r=await api('/api/scanner/check',{method:'POST',body:{productName:prefill.product||prefill.__extra?.product||null,barcode:prefill.barcode||prefill.__extra?.barcode||null,lot:prefill.lot||prefill.__extra?.lot||null,expiryDate:prefill.expiry||prefill.dlc||prefill.__extra?.expiry||null,rawCode:state.scanDetectedBarcode||null}});if(!r.duplicate)return true;return confirm(`Ce produit semble déjà avoir été enregistré${r.record?.createdAt?` le ${fmt(r.record.createdAt)}`:''}.\n\nVoulez-vous quand même continuer ?`)}catch{return true}}
async function uploadCurrentScanEvidence(kind){const file=scanEvidenceFile();if(!file?.size)return null;const up=new FormData();up.append('file',file);up.append('kind',kind);const m=await api('/api/media/upload',{method:'POST',body:up});return m.id}
async function addCurrentScanToSession(o){if(!state.scanSession||state.scanSessionBusy)return;if(!validateTraceScan(o)&&state.scanSession.kind==='series')return;const product=$('#scanProduct')?.value.trim()||o.product||'',expiry=$('#scanDate')?.value||o.expiryDate||'',lot=$('#scanLot')?.value.trim()||o.lot||'',barcode=$('#scanBarcode')?.value.trim()||o.barcode||'',quantity=Number($('#scanBatchQty')?.value||o.gs1?.quantity||1);if(!product&&!barcode)return toast('Produit ou code-barres requis.',true);state.scanSessionBusy=true;try{const mediaId=await uploadCurrentScanEvidence(state.scanSession.kind==='reception'?'scan_reception':'scan_traceability');const item=await api(`/api/scanner/sessions/${state.scanSession.id}/items`,{method:'POST',body:{productName:product||null,barcode:barcode||null,rawCode:state.scanDetectedBarcode||null,lot:lot||null,expiryDate:expiry||null,dateType:$('#scanDateType')?.value||o.dateType||'unknown',quantity,mediaId,payload:{ocrConfidence:o.ocrConfidence||null,scanConfidence:o.confidence||null,photoQuality:state.scanQuality?.score||null,weight:$('#scanWeight')?.value||null,storageTemperature:$('#scanStorage')?.value||null}}});const problems=item.anomaly_labels||[];toast(problems.length?`Ajouté · à vérifier : ${problems.join(', ')}`:'Produit ajouté à la session',problems.includes('DLC dépassée'));await refreshScanSession();startScan('dlc')}catch(e){handleError(e)}finally{state.scanSessionBusy=false}}
async function loadScannerWorkspace(){try{const active=await api('/api/scanner/sessions/active');state.scanSession=active||null;state.scanSessionItems=[];if(active)await refreshScanSession();else renderScanSessionPanel()}catch(e){console.warn('scanner workspace',e);renderScanSessionPanel()}}
async function refreshScanSession(){if(!state.scanSession?.id)return renderScanSessionPanel();const full=await api(`/api/scanner/sessions/${state.scanSession.id}`);state.scanSession=full;state.scanSessionItems=full.items||[];renderScanSessionPanel()}
function renderScanSessionPanel(){const box=$('#scanSessionPanel');if(!box)return;if(!state.scanSession){box.classList.add('hidden');box.innerHTML='';return}const s=state.scanSession,items=state.scanSessionItems||[],anomalies=items.reduce((n,x)=>n+(x.anomaly_codes?.length||0),0);box.classList.remove('hidden');box.innerHTML=`<div class="scan-session-main"><div>${hsIcon(s.kind==='reception'?'orders':'scanner','scan-session-icon')}<span><small>${s.kind==='reception'?'Réception intelligente':'Scan en série'}</small><b>${s.kind==='reception'?esc(s.supplier_name||'Fournisseur'):`${items.length} produit${items.length>1?'s':''} scanné${items.length>1?'s':''}`}</b><em>${s.order_number?`Commande ${esc(s.order_number)} · `:''}${s.invoice_number?`Facture ${esc(s.invoice_number)} · `:''}${anomalies?`${anomalies} point(s) à vérifier`:'Aucune anomalie détectée'}</em></span></div><div class="scan-session-actions"><button class="small-btn" id="sessionScanNext">Scanner</button><button class="small-btn" id="sessionView">Voir</button><button class="btn primary" id="sessionFinish">Terminer</button></div></div>`;$('#sessionScanNext').onclick=()=>startScan('dlc');$('#sessionView').onclick=viewScanSession;$('#sessionFinish').onclick=completeScanSession}
async function startScanSession(kind){if(state.scanSession?.status==='open'){toast('Une session de scan est déjà en cours.',true);return viewScanSession()}if(kind==='series'){try{state.scanSession=await api('/api/scanner/sessions',{method:'POST',body:{kind:'series'}});state.scanSessionItems=[];renderScanSessionPanel();startScan('dlc')}catch(e){handleError(e)}return}let suppliers=[];try{suppliers=await api('/api/suppliers/')}catch(e){return handleError(e)}const active=suppliers.filter(x=>x.active);if(!active.length){modal('Réception intelligente','<div class="empty"><b>Aucun fournisseur actif.</b><br>Le gérant doit d’abord créer le fournisseur dans Commandes fournisseurs.</div>');return}modal('Nouvelle réception intelligente',`<form id="smartReceptionForm"><div class="scan-source-intro">${hsIcon('orders','scan-source-icon')}<div><b>Choisissez le fournisseur</b><small>HygieSafe cherchera automatiquement la dernière commande et la dernière facture associées.</small></div></div><div class="field"><label>Fournisseur</label><select name="supplierId">${active.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></div><button class="btn primary">Commencer la réception</button></form>`);$('#smartReceptionForm').onsubmit=async e=>{e.preventDefault();try{state.scanSession=await api('/api/scanner/sessions',{method:'POST',body:{kind:'reception',supplierId:new FormData(e.currentTarget).get('supplierId')}});state.scanSessionItems=[];closeModal();renderScanSessionPanel();toast(state.scanSession.order_number?'Commande liée automatiquement':'Réception démarrée');startScan('dlc')}catch(err){handleError(err)}}}
function anomalyText(c){return ({duplicate:'Doublon possible',expired:'DLC dépassée',expiry_soon:'DLC proche',lot_missing:'Lot absent',unknown_product:'Produit non configuré',not_ordered:'Non commandé',over_ordered:'Trop reçu'})[c]||c}
async function viewScanSession(){if(!state.scanSession)return;await refreshScanSession();const items=state.scanSessionItems||[];modal(state.scanSession.kind==='reception'?'Réception en cours':'Scan en série',`<div class="scan-session-context">${state.scanSession.supplier_name?`<b>${esc(state.scanSession.supplier_name)}</b>`:''}<span>${state.scanSession.order_number?`Commande ${esc(state.scanSession.order_number)}`:'Aucune commande liée'}${state.scanSession.invoice_number?` · Facture ${esc(state.scanSession.invoice_number)}`:''}</span></div><div class="scan-batch-list">${items.length?items.map(x=>`<div class="scan-batch-item"><div><b>${esc(x.product_name||x.barcode||'Produit')}</b><small>${x.quantity} · ${x.lot?`Lot ${esc(x.lot)} · `:''}${x.expiry_date?`DLC ${String(x.expiry_date).slice(0,10).split('-').reverse().join('/')}`:''}</small>${x.anomaly_codes?.length?`<span>${x.anomaly_codes.map(anomalyText).map(esc).join(' · ')}</span>`:''}</div><button class="small-btn danger" data-remove-scan-item="${x.id}">Supprimer</button></div>`).join(''):'<div class="empty">Aucun produit scanné.</div>'}</div><div class="scan-actions"><button class="btn primary" id="batchScanAnother">Scanner un autre produit</button>${items.length?'<button class="btn" id="batchFinishFromModal">Terminer la session</button>':''}<button class="btn ghost" id="batchCancel">Annuler la session</button></div>`);$$('[data-remove-scan-item]').forEach(b=>b.onclick=async()=>{await api(`/api/scanner/sessions/${state.scanSession.id}/items/${b.dataset.removeScanItem}`,{method:'DELETE'});await refreshScanSession();viewScanSession()});$('#batchScanAnother').onclick=()=>{closeModal();startScan('dlc')};if($('#batchFinishFromModal'))$('#batchFinishFromModal').onclick=()=>{closeModal();completeScanSession()};$('#batchCancel').onclick=cancelScanSession}
async function cancelScanSession(){if(!state.scanSession)return;if(!confirm('Annuler cette session de scan ? Les produits de cette session ne seront pas enregistrés en traçabilité/réception.'))return;try{await api(`/api/scanner/sessions/${state.scanSession.id}/cancel`,{method:'POST',body:{}});state.scanSession=null;state.scanSessionItems=[];closeModal();renderScanSessionPanel();$('#scanResult')?.classList.add('hidden');toast('Session annulée')}catch(e){handleError(e)}}
async function completeScanSession(){if(!state.scanSession||state.scanSessionBusy)return;state.scanSessionBusy=true;try{const r=await api(`/api/scanner/sessions/${state.scanSession.id}/complete`,{method:'POST',body:{}});state.scanSession=null;state.scanSessionItems=[];renderScanSessionPanel();$('#scanResult')?.classList.add('hidden');const d=r.summary?.discrepancies||[],bad=(r.summary?.anomalyCount||0)+(r.summary?.discrepancyCount||0);modal(r.kind==='reception'?'Réception terminée':'Scan en série terminé',`<div class="scan-complete ${bad?'warning':''}"><b>${r.summary.itemCount} produit(s) · ${r.summary.quantityTotal} unité(s)</b><span>${bad?`${bad} point(s) à vérifier ont été détectés.`:'Aucune anomalie détectée.'}</span></div>${d.length?`<div class="scan-discrepancy-list">${d.map(x=>`<div><b>${esc(x.product)}</b><small>${x.code==='short_received'?`Commandé ${x.ordered} · reçu ${x.received}`:x.code==='over_received'?`Commandé ${x.ordered} · reçu ${x.received}`:x.code==='billed_more_than_received'?`Facturé ${x.invoiced} · reçu ${x.received}`:`Facturé ${x.invoiced} · reçu ${x.received}`}</small></div>`).join('')}</div>`:''}<button class="btn primary" id="scanCompleteClose">Fermer</button>`);$('#scanCompleteClose').onclick=closeModal;if(r.kind==='reception'&&bad)toast('Réception enregistrée avec une anomalie à traiter',true);else toast('Session enregistrée')}catch(e){handleError(e)}finally{state.scanSessionBusy=false}}
function invoicePreviewRows(lines=[]){const shown=lines.slice(0,12);if(!shown.length)return '<div class="scan-warning"><b>Aucun produit détecté</b><small>Reprenez une photo plus nette ou ajoutez les lignes manuellement après avoir choisi le fournisseur.</small></div>';return `<div class="invoice-detected"><div class="invoice-detected-head"><b>${lines.length} produit(s) détecté(s)</b><small>Les lignes peu fiables doivent être corrigées avant validation.</small></div><div class="invoice-mini-list">${shown.map(x=>`<div class="${Number(x.confidence||0)<70?'needs-check':''}"><span>${esc(x.productName)}</span><small>${x.invoiceQuantity?`Qté facture ${niceNum(x.invoiceQuantity)} · `:''}${x.unitPriceEuros!=null?`${Number(x.unitPriceEuros).toFixed(2).replace('.',',')} € · `:''}${Math.round(x.confidence||0)} %</small></div>`).join('')}</div>${lines.length>shown.length?`<small class="muted">+ ${lines.length-shown.length} autre(s) ligne(s)</small>`:''}</div>`}
function invoiceEditorRow(x={},index=0){return `<div class="invoice-edit-row ${Number(x.confidence||100)<70?'needs-check':''}" data-invoice-edit-row><div class="invoice-edit-top"><label><input type="checkbox" data-invoice-include checked> Inclure</label><span>Ligne ${index+1}${x.confidence?` · ${Math.round(x.confidence)} %`:''}</span></div><div class="field full"><label>Produit</label><input data-invoice-product value="${esc(x.productName||'')}" placeholder="Ex. Farine T55 25 kg"></div><div class="invoice-edit-grid"><div class="field"><label>Référence</label><input data-invoice-ref value="${esc(x.supplierReference||'')}"></div><div class="field"><label>Qté dernière facture</label><input data-invoice-qty type="number" min="0.001" step="0.001" value="${Number(x.invoiceQuantity||1)}"></div><div class="field"><label>Unité</label><input data-invoice-unit value="${esc(x.orderUnit||'unité')}"></div><div class="field"><label>Prix unitaire €</label><input data-invoice-price type="number" min="0" step="0.01" value="${x.unitPriceEuros==null?'':Number(x.unitPriceEuros)}"></div><input data-invoice-total type="hidden" value="${x.lineTotalEuros==null?'':Number(x.lineTotalEuros)}"><input data-invoice-raw type="hidden" value="${esc(x.rawText||'')}"></div></div>`}
async function openInvoiceOrderImport(inv,ocr){if(!isOwner())return toast('Cette action est réservée au gérant.',true);let suppliers=state.suppliers;if(!suppliers.length)suppliers=await api('/api/suppliers/');state.suppliers=suppliers;if(!suppliers.length){modal('Créer le tableau depuis une facture',`<div class="empty"><b>Ajoutez d’abord le fournisseur.</b><br>Le tableau doit être lié à un fournisseur pour préparer les commandes.</div><button class="btn primary" id="invoiceGoSuppliers">Ouvrir les fournisseurs</button>`);$('#invoiceGoSuppliers').onclick=()=>{closeModal();go('suppliers');setTimeout(()=>openSupplierForm(),50)};return}const detected=inv.lines||[];modal('Facture → tableau partagé',`<form id="invoiceImportForm"><div class="supplier-logo-note"><img src="/assets/logo-hygiesafe.svg" alt="HygieSafe"><span>Les produits validés seront ajoutés au tableau Commandes visible par les employés. Les lignes orange sont celles à vérifier en priorité.</span></div><div class="form-grid"><div class="field"><label>Fournisseur</label><select name="supplierId" required>${suppliers.filter(x=>x.active).map(s=>`<option value="${s.id}" ${String(inv.supplier||'').toLowerCase().includes(String(s.name||'').toLowerCase())?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>N° facture</label><input name="invoiceNo" value="${esc(inv.invoiceNo||'')}"></div><div class="field"><label>Date facture</label><input name="invoiceDate" type="date" value="${esc(inv.invoiceDate||'')}"></div><div class="field"><label>Total TTC</label><input name="totalTtcEuros" type="number" step="0.01" min="0" value="${inv.totalTtc??''}"></div></div><div class="invoice-editor-head"><div><b>Produits à partager</b><small>Corrigez les erreurs OCR avant validation.</small></div><button type="button" class="small-btn" id="addInvoiceLine">+ Ligne</button></div><div id="invoiceEditorRows">${(detected.length?detected:[{productName:'',invoiceQuantity:1,orderUnit:'unité'}]).map(invoiceEditorRow).join('')}</div><div class="invoice-import-footer"><small>La quantité de la facture devient la quantité habituelle conseillée. Les employés restent libres de saisir la quantité réellement nécessaire.</small><button class="btn primary">Créer et partager le tableau</button></div></form>`);$('#addInvoiceLine').onclick=()=>{const box=$('#invoiceEditorRows'),n=box.querySelectorAll('[data-invoice-edit-row]').length;box.insertAdjacentHTML('beforeend',invoiceEditorRow({productName:'',invoiceQuantity:1,orderUnit:'unité'},n))};$('#invoiceImportForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),lines=[...e.currentTarget.querySelectorAll('[data-invoice-edit-row]')].filter(row=>row.querySelector('[data-invoice-include]').checked).map(row=>({productName:row.querySelector('[data-invoice-product]').value.trim(),supplierReference:row.querySelector('[data-invoice-ref]').value.trim(),invoiceQuantity:Number(row.querySelector('[data-invoice-qty]').value||1),orderUnit:row.querySelector('[data-invoice-unit]').value.trim()||'unité',packSize:1,unitPriceEuros:row.querySelector('[data-invoice-price]').value,lineTotalEuros:row.querySelector('[data-invoice-total]').value,rawText:row.querySelector('[data-invoice-raw]').value})).filter(x=>x.productName.length>=2);if(!lines.length)return toast('Ajoutez au moins un produit.',true);const submit=e.currentTarget.querySelector('button[type="submit"],button.btn.primary:last-child');if(submit){submit.disabled=true;submit.textContent='Création du tableau…'}try{let mediaId=null;if(scanEvidenceFile()?.size){const up=new FormData();up.append('file',scanEvidenceFile());up.append('kind','invoice');const m=await api('/api/media/upload',{method:'POST',body:up});mediaId=m.id}await api('/api/suppliers/invoice-imports',{method:'POST',body:{supplierId:f.get('supplierId'),mediaId,invoiceNo:f.get('invoiceNo')||null,invoiceDate:f.get('invoiceDate')||null,totalHtEuros:inv.totalHt??null,totalTtcEuros:f.get('totalTtcEuros')||null,ocrConfidence:Math.round(ocr.ocrConfidence||ocr.confidence||0),lines}});closeModal();toast(`${lines.length} produit(s) partagés avec l’équipe`);state.supplierTab='needs';go('suppliers')}catch(err){if(submit){submit.disabled=false;submit.textContent='Créer et partager le tableau'}handleError(err)}}}
function showScanResult(o){if(state.scanMode==='invoice'){const inv=o.invoice||{},warns=inv.warnings||[];$('#scanResult').innerHTML=`${scanQualityHtml()}${warns.length?`<div class="scan-warning"><b>À vérifier</b><small>${esc(warns.join(' · '))}</small></div>`:''}<div class="scan-result-head"><div><h3>Facture analysée</h3><small>${inv.lineCount||0} ligne(s) produit détectée(s). Vérifiez les lignes orange avant validation.</small></div><span class="scan-confidence ${Number(o.ocrConfidence||0)<65?'medium':''}">${Math.round(o.ocrConfidence||o.confidence||0)} %</span></div><div class="form-grid"><div class="field"><label>Fournisseur détecté</label><input id="invSupplier" value="${esc(inv.supplier||'')}"></div><div class="field"><label>N° facture</label><input id="invNo" value="${esc(inv.invoiceNo||'')}"></div><div class="field"><label>Date facture</label><input id="invDate" type="date" value="${esc(inv.invoiceDate||'')}"></div><div class="field"><label>Total HT</label><input id="invHT" type="number" step="0.01" value="${inv.totalHt??''}"></div><div class="field"><label>Total TTC</label><input id="invTTC" type="number" step="0.01" value="${inv.totalTtc??''}"></div></div>${invoicePreviewRows(inv.lines||[])}<div class="scan-actions"><button class="btn primary owner-only" id="createOrderTableFromInvoice">Vérifier puis créer le tableau</button><button class="btn" id="saveInvoiceReception">Créer une réception</button><button class="btn ghost" id="scanAgain">Reprendre</button></div>`;if($('#createOrderTableFromInvoice'))$('#createOrderTableFromInvoice').onclick=()=>openInvoiceOrderImport({...inv,supplier:$('#invSupplier').value,invoiceNo:$('#invNo').value,invoiceDate:$('#invDate').value,totalHt:$('#invHT').value,totalTtc:$('#invTTC').value},o);$('#saveInvoiceReception').onclick=()=>openRecordForm('reception',{supplier:$('#invSupplier').value,invoiceNo:$('#invNo').value,invoiceDate:$('#invDate').value,totalHt:$('#invHT').value,totalTtc:$('#invTTC').value,__scanFile:scanEvidenceFile(),__extra:{source:'scanner_invoice',ocrConfidence:o.ocrConfidence||o.confidence||null,photoQuality:state.scanQuality?.score||null,scanVerified:true}});$('#scanAgain').onclick=()=>startScan('invoice');roleUi();return}
  const warns=o.warnings||[],fc=o.fieldConfidence||{},dateOptions=['dlc','ddm','expiry','unknown'].map(v=>`<option value="${v}" ${o.dateType===v?'selected':''}>${scanTypeLabel(v)}</option>`).join('');
  $('#scanResult').innerHTML=`${scanQualityHtml()}${warns.length?`<div class="scan-warning"><b>À vérifier avant d’enregistrer</b><small>${esc(warns.join(' · '))}</small></div>`:''}<div class="scan-result-head"><div><h3>Étiquette analysée</h3><small>${o.ocrPasses>1?'Double lecture effectuée pour améliorer le résultat':'Lecture automatique effectuée'}</small></div><span class="scan-confidence ${Number(o.confidence)<70?'medium':''}">${Math.round(o.confidence||0)} %</span></div>${productLookupHtml()}${scanField('Produit','scanProduct',o.product||'',fc.product,{placeholder:'Nom du produit'})}<div class="form-grid scan-main-fields">${scanField('Date limite','scanDate',o.date||'',fc.date,{type:'date'})}<div class="field scan-field"><label>Type de date ${confidenceTag(fc.date)}</label><select id="scanDateType">${dateOptions}</select></div>${scanField('N° de lot','scanLot',o.lot||'',fc.lot,{placeholder:'Lot / batch'})}${scanField('Code-barres','scanBarcode',o.barcode||'',fc.barcode,{placeholder:'EAN / GTIN'})}</div>${scanDateSuggestions(o)}${scanExtraMeta(o)}<details class="scan-details"><summary>Autres informations détectées</summary><div class="form-grid"><div class="field"><label>Poids ${confidenceTag(fc.weight)}</label><input id="scanWeight" value="${o.weight!=null?esc(`${o.weight} ${o.weightUnit||''}`):''}"></div><div class="field"><label>Conservation ${confidenceTag(fc.storageTemperature)}</label><input id="scanStorage" value="${(o.storageTemperature?.min!=null||o.storageTemperature?.max!=null)?esc(scanTempLabel(o.storageTemperature)):''}"></div><div class="field"><label>Date de production</label><input id="scanProduction" type="date" value="${esc(o.productionDate||'')}"></div><div class="field"><label>Date de surgélation</label><input id="scanFrozen" type="date" value="${esc(o.frozenDate||'')}"></div></div></details>${state.scanSession?`<div class="scan-batch-quantity"><div><b>${state.scanSession.kind==='reception'?'Quantité réellement reçue':'Quantité de ce produit'}</b><small>Vous pourrez corriger ou supprimer le scan avant de terminer.</small></div><input id="scanBatchQty" type="number" min="0.001" step="0.001" value="${o.gs1?.quantity||1}"></div>`:''}<div class="scan-confirm-note"><b>Dernière étape : vérifiez les champs orange.</b><span>${state.scanSession?'Le produit sera ajouté à la session en cours.':'HygieSafe n’enregistre rien automatiquement sans votre validation.'}</span></div><div class="scan-actions">${state.scanSession?'<button class="btn primary" id="addBatchScan">Ajouter et scanner le suivant</button><button class="btn" id="viewBatch">Voir la session</button><button class="btn ghost" id="finishBatch">Terminer</button>':'<button class="btn primary" id="saveTrace">Enregistrer en traçabilité</button><button class="btn" id="saveReception">Réception</button><button class="btn" id="saveArticle">Stock</button><button class="btn ghost" id="scanAgain">Reprendre</button>'}</div>`;
  $$('[data-scan-date]').forEach(b=>b.onclick=()=>{$('#scanDate').value=b.dataset.scanDate;$('#scanDateType').value=b.dataset.scanDateType||'unknown';toast('Date sélectionnée')});if(state.scanSession){$('#addBatchScan').onclick=()=>addCurrentScanToSession(o);$('#viewBatch').onclick=viewScanSession;$('#finishBatch').onclick=completeScanSession}else{$('#saveTrace').onclick=async()=>{if(validateTraceScan(o)&&await confirmNoDuplicate(scanPrefill(o)))openRecordForm('traceability',scanPrefill(o))};$('#saveReception').onclick=async()=>{const p=scanPrefill(o);if(await confirmNoDuplicate(p))openRecordForm('reception',p)};$('#saveArticle').onclick=()=>openRecordForm('stock_article',scanPrefill(o));$('#scanAgain').onclick=()=>startScan('dlc')}
}
function openManualBarcode(){modal('Saisir un code-barres',`<div class="scan-source-intro">${hsIcon('scanner','scan-source-icon')}<div><b>Saisie manuelle</b><small>Utilisez cette option uniquement si le code n’est pas détecté automatiquement.</small></div></div><form id="manualBarcodeForm"><div class="field"><label>EAN / GTIN</label><input id="manualBarcode" inputmode="numeric" autocomplete="off" placeholder="Ex. 3760123456789" required></div><button class="btn primary">Utiliser ce code</button></form>`);$('#manualBarcodeForm').onsubmit=e=>{e.preventDefault();const code=$('#manualBarcode').value.trim();if(code.length<6)return toast('Code-barres trop court.',true);closeModal();showBarcode(code)}}
async function openCameraBarcode(){let stream,timer;modal('Scanner un code-barres',`<div class="barcode-live"><video id="barcodeVideo" autoplay playsinline></video><div class="barcode-target"><span></span></div></div><p class="muted">Placez le code dans le cadre. La lecture est automatique.</p><div class="scan-actions"><button class="btn" id="barcodePhoto">Prendre une photo</button><button class="btn ghost" id="barcodeManual">Saisir manuellement</button></div>`);const stop=()=>{if(timer)clearInterval(timer);stream?.getTracks().forEach(t=>t.stop())};$('#modalClose').onclick=()=>{stop();closeModal()};$('#barcodePhoto').onclick=()=>{stop();chooseScanFile(true)};$('#barcodeManual').onclick=()=>{stop();closeModal();openManualBarcode()};try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280},height:{ideal:720}}});$('#barcodeVideo').srcObject=stream;const detector=new BarcodeDetector({formats:await supportedBarcodeFormats()});timer=setInterval(async()=>{try{const video=$('#barcodeVideo');if(!video||$('#modal').classList.contains('hidden'))return stop();const codes=await detector.detect(video);if(codes[0]){stop();closeModal();showBarcode(codes[0].rawValue)}}catch{}},280)}catch{stop();closeModal();toast('Caméra indisponible : utilisez une photo ou la saisie manuelle.',true);startScan('barcode')}}
function showBarcodePhotoResult(o){go('scanner');$('#scanResult').classList.remove('hidden');$('#scanResult').innerHTML=`${scanQualityHtml()}<div class="scan-warning"><b>Code-barres non détecté</b><small>Rapprochez-vous du code, gardez le téléphone parallèle à l’étiquette et évitez les reflets.</small></div><div class="scan-actions"><button class="btn primary" id="barcodeRetry">Reprendre une photo</button><button class="btn" id="barcodeManualFallback">Saisir le code</button></div>`;$('#barcodeRetry').onclick=()=>startScan('barcode');$('#barcodeManualFallback').onclick=openManualBarcode}
async function openRecognizedProducts(){let rows=[];try{rows=await api('/api/scanner/products?limit=150')}catch(e){return handleError(e)}const list=()=>rows.length?rows.map(x=>`<div class="recognized-product-row" data-product-code="${esc(x.barcode)}">${x.image_url?`<img src="${esc(x.image_url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:hsIcon('inventory','recognized-product-icon')}<div><b>${esc(x.product_name)}</b><small>${[x.brand,x.quantity_label,x.category].filter(Boolean).map(esc).join(' · ')||'Produit mémorisé'}</small><em>${esc(x.barcode)} · vu ${Number(x.seen_count||1)} fois</em></div><button class="small-btn" data-product-open="${esc(x.barcode)}">Ouvrir</button></div>`).join(''):'<div class="empty"><b>Aucun produit mémorisé pour le moment.</b><br>Scannez un code-barres : les produits validés apparaîtront ici.</div>';modal('Produits reconnus',`<div class="recognized-product-head"><div><b>Catalogue appris par HygieSafe</b><small>Produits validés dans cet établissement. La prochaine reconnaissance est instantanée.</small></div><input id="recognizedProductSearch" placeholder="Rechercher un produit, une marque ou un code-barres"></div><div id="recognizedProductList" class="recognized-product-list">${list()}</div>`);const input=$('#recognizedProductSearch');input.oninput=()=>{const q=input.value.trim().toLowerCase();$$('[data-product-code]').forEach(row=>row.classList.toggle('hidden',q&&!row.textContent.toLowerCase().includes(q)))};$$('[data-product-open]').forEach(b=>b.onclick=()=>{const code=b.dataset.productOpen;closeModal();showBarcode(code)})}
async function showBarcode(code){
  code=String(code||'').trim();
  go('scanner');
  state.scanProductLookup=null;
  let parsed={isGs1:false};
  try{parsed=await api('/api/scanner/parse-code',{method:'POST',body:{rawCode:code}})}catch{}
  const gs1=parsed?.isGs1;
  const gtin=String(parsed.gtin||code).replace(/\D/g,'');
  const validGtin=gtin.length>=8&&gtin.length<=14;
  $('#scanResult').classList.remove('hidden');
  $('#scanResult').innerHTML=`<div class="scan-loading enhanced"><div class="scan-spinner"></div><b>Code détecté</b><small>Recherche dans votre catalogue puis dans les bases produits disponibles…</small><div class="scan-loading-steps"><span class="on">Code</span><span class="on">Catalogue</span><span class="on">Internet</span></div></div>`;
  const lookup=validGtin?await lookupScannedProduct(gtin):null;
  const product=lookup?.found?lookup.product:null;
  const gs1Meta=gs1?`<div class="scan-meta">
    ${parsed.lot?`<span>Lot ${esc(parsed.lot)}</span>`:''}
    ${parsed.expiryDate?`<span>DLC ${esc(parsed.expiryDate.split('-').reverse().join('/'))}</span>`:''}
    ${parsed.productionDate?`<span>Production ${esc(parsed.productionDate.split('-').reverse().join('/'))}</span>`:''}
    ${parsed.quantity?`<span>Qté ${esc(parsed.quantity)}</span>`:''}
    ${parsed.weightKg!=null?`<span>${esc(parsed.weightKg)} kg</span>`:''}
  </div>`:'';
  const productBlock=validGtin?productLookupHtml(lookup):'<div class="scan-warning"><b>GTIN non exploitable</b><small>Le code a été lu, mais il ne correspond pas à un EAN/GTIN de 8 à 14 chiffres.</small></div>';
  const qtyBlock=state.scanSession?`<div class="scan-batch-quantity"><div><b>${state.scanSession.kind==='reception'?'Quantité reçue':'Quantité'}</b><small>${product?`Produit reconnu : ${esc(product.name)}`:gs1?'Les informations GS1 seront reprises automatiquement.':'Vous pourrez renseigner le produit si nécessaire.'}</small></div><input id="barcodeBatchQty" type="number" min="0.001" step="0.001" value="${parsed.quantity||1}"></div>`:'';
  const manualNameBlock=!state.scanSession&&!product&&validGtin?'<div class="field product-manual-memory"><label>Nom du produit</label><input id="barcodeManualProductName" placeholder="Ex. Mozzarella 1 kg"></div>':'';
  const alreadyKnown=!!product&&['hygiesafe_memory','hygiesafe_catalog'].includes(lookup?.source||product?.source);
  const actionBlock=state.scanSession
    ? '<button class="btn primary" id="barcodeAddBatch">Ajouter et continuer</button><button class="btn" id="barcodeViewBatch">Voir la session</button>'
    : `${product?(alreadyKnown?'<button class="btn" disabled>Déjà reconnu par HygieSafe</button>':'<button class="btn primary" id="barcodeRemember">Mémoriser dans HygieSafe</button>'):'<button class="btn primary" id="barcodeRememberManual">Mémoriser ce produit</button>'}${isManager()?'<button class="btn" id="barcodeArticle">Ajouter au stock</button>':''}`;
  $('#scanResult').innerHTML=`<div class="barcode-success">${hsIcon('scanner','scan-source-icon')}<div><span>${gs1?'GS1 / DataMatrix détecté':'Code-barres détecté'}</span><b>${esc(parsed.gtin||code)}</b></div></div>${gs1Meta}${productBlock}${qtyBlock}${manualNameBlock}<div class="scan-actions">${actionBlock}<button class="btn ghost" id="barcodeAgain">Scanner un autre code</button></div>`;

  if(state.scanSession){
    $('#barcodeAddBatch').onclick=async()=>{
      if(state.scanSessionBusy)return;
      state.scanSessionBusy=true;
      try{
        const item=await api(`/api/scanner/sessions/${state.scanSession.id}/items`,{method:'POST',body:{
          productName:product?.name||null,
          barcode:parsed.gtin||gtin||code,
          rawCode:code,
          lot:parsed.lot||null,
          expiryDate:parsed.expiryDate||null,
          dateType:parsed.dateType||'unknown',
          quantity:Number($('#barcodeBatchQty').value||1),
          payload:{gs1:parsed,productLookup:product?{code:product.code,name:product.name,brand:product.brand||null,category:product.category||null,source:product.source||null,sourceUrl:product.sourceUrl||null}:null}
        }});
        toast(item.anomaly_labels?.length?`Ajouté · ${item.anomaly_labels.join(', ')}`:`${item.product_name||product?.name||'Produit'} ajouté`);
        await refreshScanSession();
        startScan('barcode');
      }catch(e){handleError(e)}finally{state.scanSessionBusy=false}
    };
    $('#barcodeViewBatch').onclick=viewScanSession;
  }else{
    if($('#barcodeRemember'))$('#barcodeRemember').onclick=async()=>{
      try{
        await api(`/api/scanner/products/${encodeURIComponent(gtin)}/remember`,{method:'POST',body:{name:product.name}});
        toast('Produit mémorisé pour cet établissement');
        await showBarcode(code);
      }catch(e){handleError(e)}
    };
    if($('#barcodeRememberManual'))$('#barcodeRememberManual').onclick=async()=>{
      const name=$('#barcodeManualProductName')?.value.trim();
      if(!name)return toast('Renseignez le nom du produit.',true);
      try{
        await api(`/api/scanner/products/${encodeURIComponent(gtin)}/remember`,{method:'POST',body:{name}});
        toast('Produit mémorisé');
        await showBarcode(code);
      }catch(e){handleError(e)}
    };
    if($('#barcodeArticle'))$('#barcodeArticle').onclick=()=>openRecordForm('stock_article',{
      product:product?.name||$('#barcodeManualProductName')?.value||'',
      barcode:parsed.gtin||gtin||code,
      quantity:'',
      unit:product?.quantityLabel||'',
      __rememberProduct:product?.code?{code:product.code}:null,
      __extra:product?{
        brand:product.brand||null,category:product.category||null,quantityLabel:product.quantityLabel||null,imageUrl:product.imageUrl||null,
        ingredients:product.ingredients||null,allergens:product.allergens||null,traces:product.traces||null,labels:product.labels||null,
        countries:product.countries||null,origins:product.origins||null,manufacturingPlaces:product.manufacturingPlaces||null,embCodes:product.embCodes||null,
        nutritionGrade:product.nutritionGrade||null,ecoscoreGrade:product.ecoscoreGrade||null,productLookupSource:product.source||null,
        productLookupUrl:product.sourceUrl||null,productLookupLicense:product.sourceLicense||null
      }:{}
    });
  }
  $('#barcodeAgain').onclick=()=>startScan('barcode');
}

function scheduleSummary(schedule=[]){if(!Array.isArray(schedule)||!schedule.length)return 'Aucun horaire configuré';const names=['','Lun','Mar','Mer','Jeu','Ven','Sam','Dim'];const groups=new Map();schedule.forEach(d=>{const key=`${d.startTime}-${d.endTime}`;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(names[Number(d.weekday)]||d.weekday)});return [...groups.entries()].map(([hours,weekdays])=>`${weekdays.join(', ')} ${hours.replace('-', '–')}`).join(' · ')}
async function openScheduleEditor(userId){const u=state.team.find(x=>x.id===userId);if(!u)return;const byDay=new Map((u.schedule||[]).map(x=>[Number(x.weekday),x]));const labels=['','Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];const rows=[1,2,3,4,5,6,7].map(day=>{const s=byDay.get(day),active=!!s;return `<div class="schedule-row ${active?'':'off'}" data-schedule-row="${day}"><label class="schedule-day"><input type="checkbox" name="active-${day}" ${active?'checked':''}> ${labels[day]}</label><input type="time" name="start-${day}" value="${esc(s?.startTime||'07:00')}" ${active?'':'disabled'} aria-label="Début ${labels[day]}"><input type="time" name="end-${day}" value="${esc(s?.endTime||'14:00')}" ${active?'':'disabled'} aria-label="Fin ${labels[day]}"></div>`}).join('');modal(`Horaires · ${u.name}`,`<div class="schedule-help">${hsIcon('schedule','')}<span>Les températures de l’employé ne seront plus proposées toute la journée. Elles apparaîtront à son <b>heure d’arrivée</b> puis à son <b>heure de départ</b>.</span></div><form id="scheduleForm"><div class="schedule-editor">${rows}</div><button class="btn primary" style="margin-top:12px">Enregistrer les horaires</button></form>`);$$('[data-schedule-row] input[type=checkbox]').forEach(c=>c.onchange=()=>{const row=c.closest('[data-schedule-row]');row.classList.toggle('off',!c.checked);row.querySelectorAll('input[type=time]').forEach(i=>i.disabled=!c.checked)});$('#scheduleForm').onsubmit=async ev=>{ev.preventDefault();const days=[1,2,3,4,5,6,7].map(day=>{const active=ev.currentTarget.elements[`active-${day}`].checked;return {weekday:day,active,startTime:active?ev.currentTarget.elements[`start-${day}`].value:null,endTime:active?ev.currentTarget.elements[`end-${day}`].value:null}});await api(`/api/auth/team/${userId}/schedule`,{method:'PUT',body:{days}});closeModal();toast('Horaires enregistrés');await loadTeam()}}
async function refreshTemperatureAlert(){const box=$('#employeeTemperatureAlert');if(!box||state.me?.user.role!=='employee'){box?.classList.add('hidden');return}let s;try{s=await api('/api/records/temperature-alert')}catch{return}if(!s.due){box.classList.add('hidden');box.classList.remove('overdue');return}box.classList.remove('hidden');box.classList.toggle('overdue',Number(s.overdue)>0);const first=s.actions?.[0];$('#employeeAlertTitle').textContent=Number(s.overdue)>0?'Relevé de température en retard':'Relevé de température à faire maintenant';$('#employeeAlertText').textContent=`${first?.slotLabel||'Contrôle'} prévu à ${first?.scheduledAt||''} · ${s.due} appareil${s.due>1?'s':''} à relever`;$('#employeeAlertBtn').onclick=()=>go('controls')}


